{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#faf9f7;--ink:#12202b;--muted:#6b7a83;--accent:#7bb7c8;--accent-2:#f4b59b;--card:#ffffff}
    *{box-sizing:border-box}
    body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial; margin:0; color:var(--ink); background:var(--bg); -webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(123,183,200,0.06),transparent);border-bottom:1px solid rgba(18,32,43,0.06)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin-left:18px;color:var(--ink);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:0 22px}

    .hero{position:relative;background:var(--card);border-radius:16px;padding:28px;overflow:hidden;display:flex;gap:28px;align-items:center}
    .hero .copy{flex:1}
    .meta{color:var(--muted);font-size:14px;margin-bottom:8px}
    h1{margin:0 0 6px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .controls{display:flex;gap:12px;align-items:center;margin-top:18px}
    .seg{display:flex;background:rgba(18,32,43,0.04);padding:6px;border-radius:10px}
    .seg button{border:0;background:transparent;padding:8px 12px;border-radius:8px;cursor:pointer;font-weight:600}
    .seg button.active{background:linear-gradient(90deg,rgba(123,183,200,0.14),rgba(244,181,155,0.12));}
    .mixer{display:flex;gap:8px;align-items:center;padding:8px 12px;border-radius:10px;background:rgba(18,32,43,0.03)}
    .mixer input{accent-color:var(--accent)}
    .cta{margin-top:18px}
    .btn{display:inline-block;padding:10px 16px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    .btn.ghost{background:transparent;border:1px solid rgba(18,32,43,0.06);color:var(--ink)}

    .hero .visual{width:280px;height:160px;flex:0 0 280px;position:relative}
    .pattern-svg{position:absolute;inset:0;width:100%;height:100%;opacity:0.14}
    .card-row{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:18px}
    .card{background:var(--card);border-radius:12px;padding:14px;border:1px solid rgba(18,32,43,0.04)}

    .next-event{display:flex;gap:14px;align-items:center}
    .date{font-weight:800;font-size:22px;background:linear-gradient(180deg,var(--accent),var(--accent-2));-webkit-background-clip:text;background-clip:text;color:transparent}
    ul.calendar{list-style:none;padding:0;margin:12px 0 0 0}
    ul.calendar li{padding:10px 0;border-top:1px dashed rgba(18,32,43,0.04);display:flex;justify-content:space-between}
    .muted{color:var(--muted)}

    footer{margin-top:28px;padding:22px;border-top:1px solid rgba(18,32,43,0.04);display:flex;justify-content:space-between;align-items:center}
    .disclaimer{font-size:13px;color:#8a9aa3}

    /* responsive */
    @media (max-width:880px){.card-row{grid-template-columns:1fr;}.hero{flex-direction:column}.hero .visual{width:100%;height:120px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="copy">
        <div class="meta">Community sound meditations in {{CITY}}, {{STATE}}</div>
        <h1>Gather — Listen — Reset</h1>
        <p class="lead">Join small, guided sonic experiences designed to help you land in your body and soften the edges. Choose the approach that fits how you feel right now.</p>

        <div class="controls" role="region" aria-label="Mood and intensity selectors">
          <div>
            <div style="font-size:13px;color:var(--muted);margin-bottom:6px">Mood to Method</div>
            <div class="seg" id="moodSeg">
              <button data-mood="tuned">Tense</button>
              <button data-mood="drift">Scattered</button>
              <button data-mood="soft">Tender</button>
              <button data-mood="curious">Curious</button>
            </div>
          </div>

          <div>
            <div style="font-size:13px;color:var(--muted);margin-bottom:6px">Sound preference</div>
            <div class="mixer">
              <label style="font-weight:700;font-size:13px">Gentle</label>
              <input id="intensity" type="range" min="0" max="2" value="1">
              <label style="font-weight:700;font-size:13px">Intense</label>
            </div>
          </div>
        </div>

        <div class="cta">
          <a id="primaryCta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="events.html#calendar">See full schedule</a>
        </div>

        <div id="recommendation" style="margin-top:12px;color:var(--muted);font-weight:600">Recommended approach: subtle bowl layering</div>
      </div>

      <div class="visual">
        <svg class="pattern-svg" viewBox="0 0 280 160" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7bb7c8" stop-opacity="0.9"/><stop offset="1" stop-color="#f4b59b" stop-opacity="0.9"/></linearGradient>
            <pattern id="dots" x="0" y="0" width="14" height="14" patternUnits="userSpaceOnUse">
              <circle cx="2" cy="2" r="1.4" fill="#7bb7c8" opacity="0.65" />
            </pattern>
          </defs>
          <rect width="280" height="160" fill="url(#dots)" />
          <g fill="none" stroke="url(#g1)" stroke-width="2" opacity="0.12">
            <circle cx="140" cy="80" r="60" />
            <circle cx="140" cy="80" r="36" />
            <circle cx="140" cy="80" r="14" />
          </g>
        </svg>
      </div>
    </section>

    <div class="card-row">
      <div class="card">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div class="muted">Next event</div>
            <div class="next-event" style="margin-top:8px">
              <div>
                <div class="date">Sat • Apr 4</div>
                <div class="muted" style="font-size:13px">7:00 — 8:15pm</div>
              </div>
              <div style="text-align:right">
                <div style="font-weight:800">Sound Nest: Slow Bowls</div>
                <div class="muted">At our studio in {{CITY}}</div>
              </div>
            </div>
          </div>
          <div>
            <a id="nextCta" class="btn" href="book.html?event=next">Reserve a seat</a>
          </div>
        </div>

        <hr style="margin:14px 0;border:none;border-top:1px dashed rgba(18,32,43,0.04)">
        <div id="calendar">
          <div style="font-weight:700;margin-bottom:8px">Upcoming gatherings</div>
          <ul class="calendar">
            <li><span>Mar 21 • Healing Bowl Flow</span><span class="muted">$28 / 60m</span></li>
            <li><span>Apr 4 • Sound Nest: Slow Bowls</span><span class="muted">$32 / 75m</span></li>
            <li><span>Apr 12 • Gong Sketch</span><span class="muted">$36 / 75m</span></li>
            <li><span>Apr 25 • Lunar Tuning</span><span class="muted">$28 / 60m</span></li>
            <li><span>May 9 • Gentle Resonance</span><span class="muted">$24 / 50m</span></li>
            <li><span>May 21 • Deep Vessel Sound</span><span class="muted">$38 / 90m</span></li>
          </ul>
        </div>
      </div>

      <aside class="card">
        <div style="font-weight:700">How we choose an approach</div>
        <p class="muted" style="margin-top:8px">We match sound textures and pacing to what you bring. Use the Mood-to-Method control to see a suggested setup and to tailor the group focus.</p>
        <div style="margin-top:12px">
          <div style="font-weight:700;margin-bottom:6px">Accessibility & safety</div>
          <p class="muted" style="margin:0">If you have recent head injury, are pregnant, have epilepsy, or are under orders to avoid loud or vibratory stimulation, please consult with your provider before attending. If you take medication that makes you drowsy, come with support.</p>
        </div>
      </aside>
    </div>

  </main>

  <footer>
    <div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div class="muted">{{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </div>
    <div class="disclaimer">Contraindications: Avoid sound baths if advised by a medical provider. For specifics, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
  </footer>

  <script>
    (function(){
      const moodBtns = document.querySelectorAll('#moodSeg button');
      const intensity = document.getElementById('intensity');
      const rec = document.getElementById('recommendation');
      const primary = document.getElementById('primaryCta');
      const nextCta = document.getElementById('nextCta');

      const moodMap = {
        tuned: {label:'Focused Gong Flow', note:'fast release, grounding pulses'},
        drift: {label:'Breath-Weighted Bowls', note:'long, spacious tones to re-align attention'},
        soft: {label:'Slow Resonance Nest', note:'round bowls + low drones for settling'},
        curious: {label:'Exploratory Sound Sketch', note:'textural exploration, invitation to play'}
      };

      const intensityMap = [
        {tag:'gentle', desc:'soft bowl tones, minimal gong'},
        {tag:'medium', desc:'layered bowls and sympathetic drones'},
        {tag:'intense', desc:'full gong and deep frequency riding'}
      ];

      function update(){
        const mood = document.querySelector('#moodSeg button.active')?.dataset?.mood || 'soft';
        const intens = parseInt(intensity.value,10);
        const m = moodMap[mood];
        const i = intensityMap[intens];
        rec.textContent = `Recommended approach: ${m.label} — ${i.desc}. (${m.note})`;

        // update CTA phrasing
        const label = (intens===2) ? `Claim louder seat for ${m.label}` : (intens===0) ? `Reserve gentle spot for ${m.label}` : `Reserve ${m.label}`;
        primary.textContent = label;
        primary.href = `{{PRIMARY_CTA_URL}}?method=${encodeURIComponent(m.label)}&intensity=${i.tag}`;

        nextCta.href = `book.html?event=next&method=${encodeURIComponent(m.label)}&intensity=${i.tag}`;
      }

      moodBtns.forEach(btn=>btn.addEventListener('click',()=>{
        moodBtns.forEach(b=>b.classList.remove('active'));
        btn.classList.add('active');
        update();
      }));
      intensity.addEventListener('input',update);

      // set defaults
      document.querySelector('#moodSeg button[data-mood="soft"]').classList.add('active');
      update();
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdfc;--ink:#102028;--muted:#5f6e73;--accent:#9fcad1;--accent-2:#f7b99a}
    body{font-family:Inter,system-ui,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;border-bottom:1px solid rgba(16,32,40,0.04)}
    .logo{width:42px;height:42px;border-radius:9px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:800}
    nav a{margin-left:14px;text-decoration:none;color:var(--ink);font-weight:700}
    .wrap{max-width:980px;margin:26px auto;padding:0 20px}

    .intro{display:grid;grid-template-columns:1fr 260px;gap:18px;align-items:start}
    .card{background:white;border-radius:12px;padding:18px;border:1px solid rgba(16,32,40,0.04)}
    h1{margin:0 0 6px 0}
    .muted{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}
    .pkg{padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(159,202,209,0.06),transparent);text-align:center}
    .price{font-weight:800;font-size:18px}

    .mood-row{display:flex;gap:10px;margin-top:12px}
    .mood-row select,.mood-row .int{padding:8px;border-radius:10px;border:1px solid rgba(16,32,40,0.06);background:white}

    .details{margin-top:14px}
    .note{font-size:14px;color:var(--muted)}

    footer{margin-top:28px;padding:18px;border-top:1px solid rgba(16,32,40,0.04);display:flex;justify-content:space-between}

    @media(max-width:880px){.intro{grid-template-columns:1fr}.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">SB</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="intro">
      <div class="card">
        <h1>Personal Vibrational Sessions</h1>
        <div class="muted">One-on-one sound work, tailored to your nervous system.</div>
        <div class="mood-row">
          <div style="flex:1">
            <label class="muted" style="font-size:13px">Describe how you feel</label>
            <select id="moodSelect" aria-label="Mood to method select">
              <option value="settle">On edge / wound up</option>
              <option value="space">Floating / disconnected</option>
              <option value="ache">Heavy / grieving</option>
              <option value="open">Curious / exploratory</option>
            </select>
          </div>
          <div style="width:140px">
            <label class="muted" style="font-size:13px">Sound intensity</label>
            <select id="intSelect" class="int">
              <option value="gentle">Gentle</option>
              <option value="medium" selected>Medium</option>
              <option value="intense">Intense</option>
            </select>
          </div>
        </div>

        <div class="details" id="privateRec">
          <div style="font-weight:800">Suggested offering</div>
          <div id="servName" style="margin-top:6px;font-size:15px">Bespoke Bowl Session</div>
          <div id="servBlurb" class="muted" style="margin-top:8px">40–60 minutes of focused resonant work to support settling and regulation.</div>

          <div style="margin-top:12px">
            <a id="inquireBtn" class="btn" style="display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;text-decoration:none;font-weight:800" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a href="contact.html" style="margin-left:10px;text-decoration:none;color:var(--muted);font-weight:700">Ask a question</a>
          </div>
        </div>
      </div>

      <aside class="card">
        <div style="font-weight:800">Quick packages</div>
        <div class="grid">
          <div class="pkg">
            <div class="muted">Single</div>
            <div class="price">$85</div>
            <div class="muted">60 minutes, one-time</div>
          </div>
          <div class="pkg">
            <div class="muted">Mini series</div>
            <div class="price">3 for $235</div>
            <div class="muted">Three sessions, scheduled flexibly</div>
          </div>
          <div class="pkg">
            <div class="muted">Bespoke residency</div>
            <div class="price">Custom</div>
            <div class="muted">For deep, ongoing tuning — inquire</div>
          </div>
        </div>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">Contraindications: If you are pregnant, have a seizure disorder, recent concussion or implanted devices sensitive to vibration, consult your healthcare provider before booking. Inform us of medication that may increase drowsiness.</div>
      </aside>
    </div>

    <div style="margin-top:18px" class="card">
      <div style="font-weight:800">What to expect in a private session</div>
      <ul style="margin:10px 0 0 18px;color:var(--muted)">
        <li>Brief check-in and intention setting</li>
        <li>Sound layering tailored to your nervous system</li>
        <li>Space to rest, integrate, and share after the session</li>
      </ul>
    </div>
  </main>

  <footer>
    <div class="muted">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> · <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    <div class="muted">{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    (function(){
      const moodSelect = document.getElementById('moodSelect');
      const intSelect = document.getElementById('intSelect');
      const servName = document.getElementById('servName');
      const servBlurb = document.getElementById('servBlurb');
      const inquire = document.getElementById('inquireBtn');

      const map = {
        settle:{name:'Grounding Bowl Session',blurb:'Deep, low-frequency bowls to help down-regulate and release held tension.'},
        space:{name:'Anchor & Breath Session',blurb:'Bells and breath cues to ground attention into embodied clarity.'},
        ache:{name:'Holding Nest',blurb:'Extended soft resonance with careful pacing for tender or heavy days.'},
        open:{name:'Interactive Sound Lab',blurb:'A playful, exploratory session using diverse textures and invitation.'}
      };

      const intensityAdd = {
        gentle:'(very soft, minimal resonance)',
        medium:'(full warmth, layered bowls)',
        intense:'(deeper gong undertone available)'
      };

      function update(){
        const m = moodSelect.value;
        const it = intSelect.value;
        const mm = map[m];
        servName.textContent = mm.name;
        servBlurb.textContent = mm.blurb + ' ' + intensityAdd[it];

        // change CTA label and link for booking
        const ctaLabel = (it==='intense') ? `Request powerful session: ${mm.name}` : `Book: ${mm.name}`;
        inquire.textContent = ctaLabel;
        inquire.href = `{{PRIMARY_CTA_URL}}?service=${encodeURIComponent(mm.name)}&intensity=${it}`;
      }

      moodSelect.addEventListener('change',update);
      intSelect.addEventListener('change',update);
      update();
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--ink:#0f1b1f;--muted:#6b7b80;--accent:#a3d1cf;--accent-2:#f0b79e}
    body{font-family:Inter,system-ui,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid rgba(15,27,31,0.04)}
    nav a{margin-left:12px;text-decoration:none;color:var(--ink);font-weight:700}
    .wrap{max-width:1000px;margin:22px auto;padding:0 18px}
    h1{margin:8px 0}

    .lead{color:var(--muted)}
    .plans{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}
    .panel{background:white;border-radius:12px;padding:16px;border:1px solid rgba(15,27,31,0.04)}
    .tiers{display:flex;gap:10px}
    .tier{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(163,209,207,0.05),transparent);text-align:center}
    .tier .price{font-weight:800;font-size:20px}

    .controls{display:flex;gap:10px;align-items:center;margin-top:12px}
    .controls select{padding:8px;border-radius:8px;border:1px solid rgba(15,27,31,0.06)}
    .recommend{margin-top:12px;font-weight:800}
    .fineprint{color:var(--muted);font-size:13px;margin-top:12px}

    @media(max-width:880px){.plans{grid-template-columns:1fr}.tiers{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><div style="width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:800">SB</div><div style="font-weight:800">{{BUSINESS_NAME}}</div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Investment & packages</h1>
    <p class="lead">Transparent pricing for groups and private sound work. Use the mood and intensity controls to see which package fits your needs.</p>

    <div class="plans">
      <div class="panel">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:800">Cohort & Drop-in options</div>
            <div class="fineprint">Designed for small groups and recurring cohorts.</div>
          </div>
          <div style="text-align:right">
            <div style="font-weight:800">{{CITY}}, {{STATE}}</div>
            <div class="muted">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </div>

        <div style="margin-top:12px" class="tiers" id="tiers">
          <div class="tier">
            <div class="muted">Drop-in</div>
            <div class="price">$28</div>
            <div class="muted">Single session</div>
          </div>
          <div class="tier">
            <div class="muted">Cohort pass</div>
            <div class="price">$75</div>
            <div class="muted">3 sessions (cohort)</div>
          </div>
          <div class="tier">
            <div class="muted">Full series</div>
            <div class="price">$140</div>
            <div class="muted">6 sessions — best value</div>
          </div>
        </div>

        <div class="controls">
          <div>
            <label class="muted" style="font-size:13px">Mood</label>
            <select id="pkMood" aria-label="Mood selector">
              <option value="calm">Tired / Need rest</option>
              <option value="unstable">Anxious / Ramped</option>
              <option value="healing">Recovering / Grief</option>
              <option value="explore">Want to experiment</option>
            </select>
          </div>

          <div>
            <label class="muted" style="font-size:13px">Sound intensity</label>
            <select id="pkIntensity">
              <option value="gentle">Gentle</option>
              <option value="medium" selected>Medium</option>
              <option value="intense">Intense</option>
            </select>
          </div>
        </div>

        <div id="pkgRec" class="recommend">We recommend: Cohort pass — Great for steady recalibration.</div>
        <div class="fineprint">All cohort seats are limited. Pricing is inclusive of materials and studio use. Contraindications: check health considerations before attending.</div>
        <div style="margin-top:12px"><a id="bookPkg" class="btn" style="padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;text-decoration:none;font-weight:800" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </div>

      <aside class="panel">
        <div style="font-weight:800">Custom & corporate</div>
        <p class="muted">We offer private pop-up sound baths for workplaces and retreats. Pricing is customized — contact us with dates and headcount.</p>
        <div style="margin-top:12px;font-weight:700" id="matchTag">Best match: Cohort pass</div>
        <div style="margin-top:10px;font-size:13px;color:var(--muted)">Need invoice? Reach out: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </aside>
    </div>
  </main>

  <footer style="padding:18px;border-top:1px solid rgba(15,27,31,0.04);display:flex;justify-content:space-between">
    <div class="muted">{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
    <div class="muted">All packages are cohort-model friendly — schedule a block for groups.</div>
  </footer>

  <script>
    (function(){
      const mood = document.getElementById('pkMood');
      const intensity = document.getElementById('pkIntensity');
      const rec = document.getElementById('pkgRec');
      const matchTag = document.getElementById('matchTag');
      const book = document.getElementById('bookPkg');

      function choose(){
        const m = mood.value;
        const it = intensity.value;
        let pick = 'Cohort pass';
        let note = 'Great for steady recalibration.';

        if(m === 'unstable'){
          pick = (it==='intense') ? 'Drop-in + grounding add-on' : 'Cohort pass';
          note = (it==='intense') ? 'Use a single intense session with integration support.' : 'Regular attendance helps build resilience.';
        }
        if(m === 'healing'){
          pick = 'Full series';
          note = 'Longer sequence supports gradual rewiring.';
        }
        if(m === 'explore'){
          pick = 'Drop-in';
          note = 'Try different textures before committing to a series.';
        }

        rec.textContent = `We recommend: ${pick} — ${note}`;
        matchTag.textContent = `Best match: ${pick}`;
        book.href = `{{PRIMARY_CTA_URL}}?package=${encodeURIComponent(pick)}&mood=${m}&intensity=${it}`;
        book.textContent = (pick==='Drop-in') ? 'Book a drop-in' : (pick==='Full series') ? 'Start the series' : 'Reserve pass';
      }

      mood.addEventListener('change',choose);
      intensity.addEventListener('change',choose);
      choose();
    })();
  </script>
